wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;

struct Node;

const MAX_QUESTION_CHARS: usize = 512;
const NO_KNOWLEDGE: &str = "no knowledge-base entry matched this question";

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        // requires: question has at most 512 characters. The bound is re-applied
        // here so that the ensures clause holds even if the precondition is not met.
        let question: String = query
            .query
            .question
            .chars()
            .take(MAX_QUESTION_CHARS)
            .collect();

        let mut knowledge = kb_read::lookup(&question);

        // ensures: knowledge is present. An empty lookup is replaced with an explicit
        // marker so the output never carries an empty knowledge list.
        if knowledge.is_empty() {
            knowledge.push(NO_KNOWLEDGE.to_string());
        }

        ConversationContext {
            intent: query.query.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
